-- Sprint 6: unified cash activity and transaction-derived management reporting.
create table public.cash_adjustments(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,adjustment_date date not null,adjustment_type text not null check(adjustment_type in('owner_capital','owner_withdrawal','other_inflow','other_outflow','correction')),direction text not null check(direction in('IN','OUT')),amount numeric(14,2)not null check(amount>0),payment_method text not null default'other'check(payment_method in('cash','momo','bank_transfer','other')),description text not null check(char_length(trim(description))between 2 and 300),reference text,notes text,status text not null default'active'check(status in('active','voided')),voided_at timestamptz,voided_by uuid references public.profiles(id),void_reason text,created_at timestamptz not null default now(),created_by uuid not null references public.profiles(id),check((adjustment_type in('owner_capital','other_inflow')and direction='IN')or(adjustment_type in('owner_withdrawal','other_outflow')and direction='OUT')or adjustment_type='correction'));
create index cash_adjustments_farm_date_idx on public.cash_adjustments(farm_id,adjustment_date desc);create index cash_adjustments_farm_method_idx on public.cash_adjustments(farm_id,payment_method,adjustment_date);create index feed_movements_reporting_idx on public.feed_inventory_movements(farm_id,movement_type,movement_date);create trigger cash_adjustments_updated_at before update on public.cash_adjustments for each row execute function public.set_updated_at();
alter table public.cash_adjustments enable row level security;create policy cash_adjustments_read_management on public.cash_adjustments for select to authenticated using(public.has_farm_role(farm_id,array['admin','manager']));grant select on public.cash_adjustments to authenticated;grant all on public.cash_adjustments to service_role;

create function public.reporting_farm(financial boolean default true)returns uuid language plpgsql stable security definer set search_path='' as $$declare f uuid;begin select farm_id into f from public.farm_members where user_id=auth.uid()and active and(financial=false or role=any(array['admin','manager']))order by created_at limit 1;if f is null then raise exception'Report access denied'using errcode='42501';end if;return f;end;$$;
create function public.create_cash_adjustment(adjustment_date date,adjustment_type text,direction text,amount numeric,payment_method text,description text,reference text default null,notes text default null)returns public.cash_adjustments language plpgsql security definer set search_path='' as $$declare f uuid;r public.cash_adjustments;begin f:=public.reporting_farm(true);if not public.has_farm_role(f,array['admin'])then raise exception'Admin access required'using errcode='42501';end if;if $2 not in('owner_capital','owner_withdrawal','other_inflow','other_outflow','correction')or upper($3)not in('IN','OUT')or $4<=0 or $5 not in('cash','momo','bank_transfer','other')or char_length(trim($6))<2 or($2 in('owner_capital','other_inflow')and upper($3)<>'IN')or($2 in('owner_withdrawal','other_outflow')and upper($3)<>'OUT')then raise exception'Invalid cash adjustment'using errcode='23514';end if;insert into public.cash_adjustments(farm_id,adjustment_date,adjustment_type,direction,amount,payment_method,description,reference,notes,created_by)values(f,$1,$2,upper($3),$4,$5,trim($6),nullif(trim($7),''),nullif(trim($8),''),auth.uid())returning*into r;return r;end;$$;
create function public.void_cash_adjustment(target_adjustment uuid,reason text)returns void language plpgsql security definer set search_path='' as $$declare f uuid;begin select farm_id into f from public.cash_adjustments where id=$1 for update;if f is null or not public.has_farm_role(f,array['admin'])or char_length(trim($2))<3 then raise exception'Adjustment void denied'using errcode='42501';end if;update public.cash_adjustments set status='voided',voided_at=now(),voided_by=auth.uid(),void_reason=trim($2)where id=$1 and status='active';end;$$;

create view public.v_cash_ledger with(security_invoker=true)as
select p.farm_id,p.id transaction_id,p.payment_date transaction_date,'customer_payment'::text source_type,p.sale_id source_id,'IN'::text direction,p.amount,p.payment_method,coalesce(s.sale_number,'Customer payment')description,p.reference,p.created_at from public.customer_payments p join public.sales s on s.id=p.sale_id where p.voided_at is null and s.status='completed'
union all select p.farm_id,p.id,p.payment_date,'feed_purchase_payment',p.feed_purchase_id,'OUT',p.amount,p.payment_method,coalesce(x.purchase_number,'Feed purchase payment'),p.reference,p.created_at from public.feed_purchase_payments p join public.feed_purchases x on x.id=p.feed_purchase_id where p.voided_at is null and x.status='completed'
union all select p.farm_id,p.id,p.payment_date,'expense_payment',p.expense_id,'OUT',p.amount,p.payment_method,coalesce(x.expense_number,'Expense payment'),p.reference,p.created_at from public.expense_payments p join public.expenses x on x.id=p.expense_id where p.voided_at is null and x.status='active'
union all select a.farm_id,a.id,a.adjustment_date,'cash_adjustment',a.id,a.direction,a.amount,a.payment_method,a.description,a.reference,a.created_at from public.cash_adjustments a where a.status='active';
grant select on public.v_cash_ledger to authenticated;

create function public.get_cash_flow_summary(start_date date,end_date date)returns table(opening_balance numeric,total_inflows numeric,total_outflows numeric,net_movement numeric,closing_balance numeric)language plpgsql stable security definer set search_path='' as $$declare f uuid;o numeric;i numeric;outv numeric;begin f:=public.reporting_farm(true);if $1 is null or $2 is null or $1>$2 then raise exception'Invalid report date range'using errcode='22023';end if;select fa.opening_cash_balance+coalesce(sum(case when l.direction='IN'then l.amount else-l.amount end)filter(where l.transaction_date<$1),0)into o from public.farms fa left join public.v_cash_ledger l on l.farm_id=fa.id where fa.id=f group by fa.id;select coalesce(sum(amount)filter(where direction='IN'),0),coalesce(sum(amount)filter(where direction='OUT'),0)into i,outv from public.v_cash_ledger where farm_id=f and transaction_date between $1 and $2;return query select o,i,outv,i-outv,o+i-outv;end;$$;
create function public.get_profitability_summary(start_date date,end_date date)returns table(revenue numeric,feed_consumption_cost numeric,feed_wastage_cost numeric,other_operating_expenses numeric,operating_profit numeric,operating_margin_percentage numeric)language plpgsql stable security definer set search_path='' as $$declare f uuid;r numeric;c numeric;w numeric;e numeric;p numeric;begin f:=public.reporting_farm(true);if $1 is null or $2 is null or $1>$2 then raise exception'Invalid report date range'using errcode='22023';end if;select coalesce(sum(total_amount),0)into r from public.sales where farm_id=f and status='completed'and sale_date between $1 and $2;select coalesce(sum(total_cost_snapshot)filter(where movement_type='consumption'),0),coalesce(sum(total_cost_snapshot)filter(where movement_type='wastage'),0)into c,w from public.feed_inventory_movements where farm_id=f and movement_date between $1 and $2;select coalesce(sum(amount),0)into e from public.expenses where farm_id=f and status='active'and expense_date between $1 and $2;p:=r-c-w-e;return query select r,c,w,e,p,case when r=0 then null else round(p/r*100,2)end;end;$$;
create function public.get_production_report(start_date date,end_date date,target_flock uuid default null)returns table(eggs_collected bigint,good_eggs bigint,cracked_eggs bigint,cracked_percentage numeric,hen_day_percentage numeric,feed_consumed_kg numeric,feed_per_egg numeric,feed_grams_per_bird numeric,deaths bigint,culls bigint)language plpgsql stable security definer set search_path='' as $$declare f uuid;begin f:=public.reporting_farm(false);if $1>$2 or(target_flock is not null and not exists(select 1 from public.flocks where id=target_flock and farm_id=f))then raise exception'Invalid report filter'using errcode='22023';end if;return query select coalesce(sum(p.eggs_collected),0),coalesce(sum(p.eggs_collected-p.cracked_eggs),0),coalesce(sum(p.cracked_eggs),0),case when sum(p.eggs_collected)=0 then 0 else round(sum(p.cracked_eggs)::numeric/sum(p.eggs_collected)*100,2)end,case when sum(m.live_birds)=0 then null else round(sum(p.eggs_collected)::numeric/sum(m.live_birds)*100,2)end,coalesce(sum(p.feed_consumed_kg),0),case when sum(p.eggs_collected)=0 then null else round(sum(p.feed_consumed_kg)/sum(p.eggs_collected),4)end,case when sum(m.live_birds)=0 then null else round(sum(p.feed_consumed_kg)*1000/sum(m.live_birds),2)end,coalesce(sum(p.deaths),0),coalesce(sum(p.culls),0)from public.daily_production_records p join public.v_daily_production_metrics m on m.production_id=p.id where p.farm_id=f and p.production_date between $1 and $2 and(target_flock is null or p.flock_id=target_flock);end;$$;
create function public.get_sales_report_summary(start_date date,end_date date,target_customer uuid default null)returns table(revenue numeric,eggs_sold bigint,sales_count bigint,average_sale_value numeric,amount_paid numeric,outstanding_receivables numeric)language plpgsql stable security definer set search_path='' as $$declare f uuid;begin f:=public.reporting_farm(true);if $1>$2 then raise exception'Invalid report date range'using errcode='22023';end if;return query select coalesce(sum(s.total_amount),0),coalesce(sum((select sum(i.total_eggs)from public.sale_items i where i.sale_id=s.id)),0)::bigint,count(*)::bigint,coalesce(avg(s.total_amount),0),coalesce(sum((select sum(p.amount)from public.customer_payments p where p.sale_id=s.id and p.voided_at is null and p.payment_date<=$2)),0),coalesce(sum(s.total_amount-coalesce((select sum(p.amount)from public.customer_payments p where p.sale_id=s.id and p.voided_at is null and p.payment_date<=$2),0)),0)from public.sales s where s.farm_id=f and s.status='completed'and s.sale_date between $1 and $2 and(target_customer is null or s.customer_id=target_customer);end;$$;
create function public.get_expense_report_summary(start_date date,end_date date,target_category uuid default null,target_source text default null)returns table(expenses_incurred numeric,amount_paid numeric,outstanding_payables numeric,expense_count bigint)language plpgsql stable security definer set search_path='' as $$declare f uuid;begin f:=public.reporting_farm(true);if $1>$2 then raise exception'Invalid report date range'using errcode='22023';end if;return query select coalesce(sum(e.amount),0),coalesce(sum((select sum(p.amount)from public.expense_payments p where p.expense_id=e.id and p.voided_at is null and p.payment_date<=$2)),0),coalesce(sum(e.amount-coalesce((select sum(p.amount)from public.expense_payments p where p.expense_id=e.id and p.voided_at is null and p.payment_date<=$2),0)),0),count(*)::bigint from public.expenses e where e.farm_id=f and e.status='active'and e.expense_date between $1 and $2 and(target_category is null or e.category_id=target_category)and(target_source is null or e.source_type=target_source);end;$$;
create function public.get_feed_report_summary(start_date date,end_date date,target_feed_type uuid default null,target_supplier uuid default null)returns table(purchased_kg numeric,purchase_value numeric,consumed_kg numeric,consumption_cost numeric,wastage_kg numeric,wastage_cost numeric,supplier_paid numeric,supplier_payable numeric,current_stock numeric,current_inventory_value numeric)language plpgsql stable security definer set search_path='' as $$declare f uuid;begin f:=public.reporting_farm(true);if $1>$2 then raise exception'Invalid report date range'using errcode='22023';end if;return query select coalesce((select sum(total_kg)from public.feed_purchases where farm_id=f and status='completed'and purchase_date between $1 and $2 and(target_feed_type is null or feed_type_id=target_feed_type)and(target_supplier is null or supplier_id=target_supplier)),0),coalesce((select sum(total_cost)from public.feed_purchases where farm_id=f and status='completed'and purchase_date between $1 and $2 and(target_feed_type is null or feed_type_id=target_feed_type)and(target_supplier is null or supplier_id=target_supplier)),0),coalesce((select sum(quantity_kg)from public.feed_inventory_movements where farm_id=f and movement_type='consumption'and movement_date between $1 and $2 and(target_feed_type is null or feed_type_id=target_feed_type)),0),coalesce((select sum(total_cost_snapshot)from public.feed_inventory_movements where farm_id=f and movement_type='consumption'and movement_date between $1 and $2 and(target_feed_type is null or feed_type_id=target_feed_type)),0),coalesce((select sum(quantity_kg)from public.feed_inventory_movements where farm_id=f and movement_type='wastage'and movement_date between $1 and $2 and(target_feed_type is null or feed_type_id=target_feed_type)),0),coalesce((select sum(total_cost_snapshot)from public.feed_inventory_movements where farm_id=f and movement_type='wastage'and movement_date between $1 and $2 and(target_feed_type is null or feed_type_id=target_feed_type)),0),coalesce((select sum(pp.amount)from public.feed_purchase_payments pp join public.feed_purchases fp on fp.id=pp.feed_purchase_id where pp.farm_id=f and pp.voided_at is null and pp.payment_date<=$2 and(target_feed_type is null or fp.feed_type_id=target_feed_type)and(target_supplier is null or fp.supplier_id=target_supplier)),0),coalesce((select sum(fp.total_cost-coalesce((select sum(pp.amount)from public.feed_purchase_payments pp where pp.feed_purchase_id=fp.id and pp.voided_at is null and pp.payment_date<=$2),0))from public.feed_purchases fp where fp.farm_id=f and fp.status='completed'and fp.purchase_date<=$2 and(target_feed_type is null or fp.feed_type_id=target_feed_type)and(target_supplier is null or fp.supplier_id=target_supplier)),0),coalesce((select sum(quantity_kg)from public.feed_inventory_balances where farm_id=f and(target_feed_type is null or feed_type_id=target_feed_type)),0),coalesce((select sum(inventory_value)from public.feed_inventory_balances where farm_id=f and(target_feed_type is null or feed_type_id=target_feed_type)),0);end;$$;
create function public.get_health_report_summary(start_date date,end_date date,target_flock uuid default null,target_type text default null)returns table(record_count bigint,health_cost numeric,upcoming_count bigint)language plpgsql stable security definer set search_path='' as $$declare f uuid;begin f:=public.reporting_farm(true);if $1>$2 then raise exception'Invalid report date range'using errcode='22023';end if;return query select count(*)::bigint,coalesce(sum(cost),0),count(*)filter(where next_due_date is not null and next_due_date>$2)::bigint from public.health_records where farm_id=f and status='active'and record_date between $1 and $2 and(target_flock is null or flock_id=target_flock)and(target_type is null or health_type=target_type);end;$$;

revoke all on function public.reporting_farm(boolean)from public;revoke all on function public.create_cash_adjustment(date,text,text,numeric,text,text,text,text),public.void_cash_adjustment(uuid,text),public.get_cash_flow_summary(date,date),public.get_profitability_summary(date,date),public.get_production_report(date,date,uuid),public.get_sales_report_summary(date,date,uuid),public.get_expense_report_summary(date,date,uuid,text),public.get_feed_report_summary(date,date,uuid,uuid),public.get_health_report_summary(date,date,uuid,text)from public;
grant execute on function public.create_cash_adjustment(date,text,text,numeric,text,text,text,text),public.void_cash_adjustment(uuid,text),public.get_cash_flow_summary(date,date),public.get_profitability_summary(date,date),public.get_production_report(date,date,uuid),public.get_sales_report_summary(date,date,uuid),public.get_expense_report_summary(date,date,uuid,text),public.get_feed_report_summary(date,date,uuid,uuid),public.get_health_report_summary(date,date,uuid,text)to authenticated;
